//===- mac_sparse.cc --------------------------------------------*- C++ -*-===//
//
// alt capture kernel for sparse MAC config mode (2, 3, 2) `4x16_16x4`
// (GENERATED by tools/gen_mac_sparse.py). Per tile and signedness flavour it calls the narrow-encoding builtin directly (the header intrinsic of this mode uses the other),
// then runs mul, mul, mul.
// Chunk layout: 9 operand blocks of T tiles (A0 D0 M0 A1 D1 M1 A2 D2 M2).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

// Peano builds see no Chess-side define; the stream/ADF half of aie_api is not needed.
#ifndef __AIE_API_AIE_ADF_HPP__
#define __AIE_API_AIE_ADF_HPP__
#endif
#include <aie_api/aie.hpp>

typedef char v128c_t __attribute__((vector_size(128)));
typedef char v64c_t __attribute__((vector_size(64)));
typedef short v32s_t __attribute__((vector_size(64)));
#define T 32
#define OUT_WORDS_PER_TILE 48

#define STORE(r, dst) \
  do { aie::accum<accfloat, 16> w(r); aie::store_v((float *)(dst), w.to_vector<float>()); } while (0)

extern "C" {

void mac_sparse(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  uint8_t *in2 = in + 0 + T * 64 + T * 64;
  uint8_t *in3 = in + 0 + T * 64 + T * 64 + T * 16;
  uint8_t *in4 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64;
  uint8_t *in5 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64;
  uint8_t *in6 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16;
  uint8_t *in7 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16 + T * 64;
  uint8_t *in8 = in + 0 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64 + T * 16 + T * 64 + T * 64;
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // bf
      const int conf = ((0 << 9) | (0 << 8) | (2 << 1) | (3 << 3) | (2 << 5));
      v32bfloat16 a0 = *(v32bfloat16 *)(in0 + n * 64);
      v32bfloat16 d0 = *(v32bfloat16 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v32bfloat16 a1 = *(v32bfloat16 *)(in3 + n * 64);
      v32bfloat16 d1 = *(v32bfloat16 *)(in4 + n * 64);
      sparsity_t m1 = *(sparsity_t *)(in5 + n * 16);
      v32bfloat16 a2 = *(v32bfloat16 *)(in6 + n * 64);
      v32bfloat16 d2 = *(v32bfloat16 *)(in7 + n * 64);
      sparsity_t m2 = *(sparsity_t *)(in8 + n * 16);
      auto r0 = __builtin_aiev2_I512_I1024_ACC1024_accfloat_bf_mul_conf(a0, d0, m0, conf);
      auto r1 = __builtin_aiev2_I512_I1024_ACC1024_accfloat_bf_mul_conf(a1, d1, m1, conf);
      auto r2 = __builtin_aiev2_I512_I1024_ACC1024_accfloat_bf_mul_conf(a2, d2, m2, conf);
      STORE(r0, o + 0);
      STORE(r1, o + 16);
      STORE(r2, o + 32);
    }
  }
  event1();
}

} // extern "C"
